def smooth_l1_loss(input: torch.Tensor, target: torch.Tensor, beta: float,
    reduction: str='none') ->torch.Tensor:
    diff = torch.abs(input - target)
    loss = torch.where(
        diff < beta,
        0.5 * diff ** 2 / beta,
        diff - 0.5 * beta
    )

    if reduction == 'none':
        return loss
    elif reduction == 'mean':
        if loss.numel() == 0:
            return loss.sum()
        return loss.mean()
    elif reduction == 'sum':
        return loss.sum()
    else:
        raise ValueError(f"Invalid reduction mode: {reduction}")
